// Weapon card bars (wstars.js, generated by tools/wstars.js): every matrix weapon has measured bars, 1 to 5, and
// they are not the old flat [3, 3, 3, 3].
const { chromium } = require('playwright');
(async () => {
  const b = await chromium.launch(); const page = await b.newPage();
  const errors = []; page.on('pageerror', e => errors.push(e.message));
  await page.goto('file://' + require('path').resolve(__dirname, '../web/index.html'));
  await page.evaluate(() => { window.TUT_OFF = 1; splashEnd(); }); await page.waitForTimeout(300);
  const bad = await page.evaluate(() => {
    const bad = [];
    for (const id of MATRIX_ONLY.weapons.filter(i => WEAPONS[i])) {
      const s = WEAPONS[id].stars;
      if (!WSTARS[id]) bad.push('no measured bars: ' + id + ' (rerun tests/tools/wstars.js)');
      else if (s !== WSTARS[id] || s.length !== 4 || s.some(n => !(n >= 1 && n <= 5))) bad.push('bars wrong: ' + id + ' ' + JSON.stringify(s));
    }
    for (let k = 0; k < 4; k++) if (new Set(Object.values(WSTARS).map(s => s[k])).size < 3) bad.push('bar ' + k + ' barely varies');
    return bad;
  });
  if (bad.length || errors.length) console.log('FAIL', bad, 'ERRORS', errors); else console.log('PASS wstarstest');
  console.log('ERRORS', JSON.stringify(errors));
  await b.close();
})();
